package com.yuegang.zhihui.system.infrastructure;
import com.yuegang.zhihui.system.api.*;import com.yuegang.zhihui.system.domain.*;import java.util.*;import javax.sql.DataSource;import org.springframework.jdbc.core.*;import org.springframework.jdbc.datasource.*;import org.springframework.transaction.support.*;
public final class JdbcAuthorizationRepository implements AuthorizationRepository{
 private final JdbcTemplate jdbc;private final TransactionTemplate tx;public JdbcAuthorizationRepository(DataSource d){jdbc=new JdbcTemplate(d);tx=new TransactionTemplate(new DataSourceTransactionManager(d));}
 public AuthoritySnapshot snapshot(long user){Long v=jdbc.query("SELECT version FROM system_user_authorization WHERE user_id=?",r->r.next()?r.getLong(1):null,user);if(v==null)return new AuthoritySnapshot(Long.toString(user),Set.of("USER"),Set.of("profile:self:read","profile:self:write"),0);var roles=new LinkedHashSet<>(jdbc.queryForList("SELECT r.code FROM system_user_role ur JOIN system_role r ON r.id=ur.role_id WHERE ur.user_id=? AND r.enabled=TRUE ORDER BY r.code",String.class,user));if(roles.isEmpty())roles.add("USER");var permissions=new LinkedHashSet<>(jdbc.queryForList("SELECT DISTINCT p.code FROM system_user_role ur JOIN system_role_permission rp ON rp.role_id=ur.role_id JOIN system_permission p ON p.id=rp.permission_id AND p.enabled=TRUE JOIN system_role r ON r.id=ur.role_id AND r.enabled=TRUE WHERE ur.user_id=? ORDER BY p.code",String.class,user));return new AuthoritySnapshot(Long.toString(user),roles,permissions,v);}
 public Optional<AuthoritySnapshot> replaceRoles(long user,long version,Set<String> roles,long operator,String reason){return tx.execute(s->{List<Map<String,Object>> found=roles.isEmpty()?List.of():jdbc.queryForList("SELECT id,code FROM system_role WHERE code IN ("+String.join(",",Collections.nCopies(roles.size(),"?"))+") AND enabled=TRUE",roles.toArray());if(found.size()!=roles.size())return Optional.empty();jdbc.update("INSERT INTO system_user_authorization(user_id,version) VALUES(?,0) ON DUPLICATE KEY UPDATE user_id=VALUES(user_id)",user);Long current=jdbc.query("SELECT version FROM system_user_authorization WHERE user_id=? FOR UPDATE",r->r.next()?r.getLong(1):null,user);if(current==null||current!=version)return Optional.empty();var old=snapshot(user).roles();jdbc.update("DELETE FROM system_user_role WHERE user_id=?",user);for(var row:found)jdbc.update("INSERT INTO system_user_role(user_id,role_id,assigned_by) VALUES(?,?,?)",user,((Number)row.get("id")).longValue(),operator);jdbc.update("UPDATE system_user_authorization SET version=version+1 WHERE user_id=?",user);jdbc.update("INSERT INTO system_authorization_audit(user_id,operator_user_id,old_roles,new_roles,reason) VALUES(?,?,?,?,?)",user,operator,String.join(",",new TreeSet<>(old)),String.join(",",new TreeSet<>(roles)),reason==null||reason.isBlank()?null:reason.trim());return Optional.of(snapshot(user));});}
}
